using System;
using Fanex.Result.Core.Base;
using Fanex.Result.Core.Base.Utilities;

namespace LiveCasinoResultForSexyGaming
{
    public class ResultPop : IResultPopup
    {
        private static string _ImgPath = "";
        private static string strPlayerCardValue = "";
        private static string strBankerCardValue = "";
        private static string strPlayerImg = "";
        private static string strBankerImg = "";
        private static IRefDataHelper refDataHelper;

        public ResultPop(string ImgPath, IRefDataHelper refDataHelper)
        {
            _ImgPath = ImgPath;
            ResultPop.refDataHelper = refDataHelper ?? ResultCoreManager.RefDataHelper;
        }

        public string genResultPopHtml(string TransDesc, string GameId3rd, string slang, string bettype)
        {
            try
            {
                switch (bettype)
                {
                    case "3101":
                        return GetBaccaratLayout(TransDesc, slang, GameId3rd, bettype);
                    case "3102":
                        return GetDragonTigerLayout(TransDesc, slang, GameId3rd, bettype);
                    case "3103":
                        return GetSicBoLayout(TransDesc, slang, GameId3rd, bettype);
                    case "3104":
                        return GetRouletteLayout(TransDesc, slang, GameId3rd, bettype);
                    case "3105":
                        return GetDragonTigerLayout(TransDesc, slang, GameId3rd, bettype);

                    default:
                        return "";
                }
            }
            catch (Exception ex)
            {
                throw ex;
            }
        }

        private static string GetBaccaratLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            string[] GameDetail = sDesc.Split('*');
            string s1 = GetSplitValue('=', GameDetail[5].ToString());
            string[] CardValue = s1.Replace("B;", "").Replace("P;", "").Replace("0", "").Replace(";", ",").Split(':');
            strBankerCardValue = CardValue[0].ToString();
            strPlayerCardValue = CardValue[1].ToString();
            RenderTemplate();

            string[] strResult = GetSplitValue('=', GameDetail[7].ToString()).Split(';');
            string strFinalScore = "";
            string strRefKey = "SC_BT";
            for (int j = 0; j < strResult.Length; j++)
            {
                if (strFinalScore == "")
                    strFinalScore = refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
                else
                    strFinalScore = strFinalScore + ", " + refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
            }
            string strScoreValue = GameDetail[6].ToString();
            string[] strScore = GetSplitValue('=', strScoreValue).Replace("B;", "").Replace("P;", "").Split(':');
            string strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout, "Game ID : " + GameId3rd, "Player", "Banker", strPlayerImg, strBankerImg, strScore[1].ToString(), strScore[0].ToString(), strFinalScore);
        }

        private static string GetRouletteLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            string[] GameDetail = sDesc.Split('*');

            string strImgValue = GetSplitValue('=', GameDetail[5].ToString());
            string strImgUrl = GenImgUrl("Roulette", strImgValue);
            string strFinalScore = "";
            string[] strResult = GetSplitValue('=', GameDetail[7].ToString()).Split(';');
            string strRefKey = "SC_BT";
            for (int j = 0; j < strResult.Length; j++)
            {
                if (j == 0)
                    strFinalScore += refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
                else
                    strFinalScore += ", " + refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
            }
            string strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout, "Game ID : " + GameId3rd, "Results", strImgUrl, strFinalScore);
        }

        private static string GetSicBoLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            string[] GameDetail = sDesc.Split('*');

            string strImgValue = GetSplitValue('=', GameDetail[5].ToString());
            string strImgUrl = GenImgUrl("SicBo", strImgValue);
            string strFinalScore = "";
            string[] strResult = GetSplitValue('=', GameDetail[7].ToString()).Split(';');
            string strRefKey = "SC_BT";
            for (int j = 0; j < strResult.Length; j++)
            {
                if (j == 0)
                    strFinalScore += refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
                else
                    strFinalScore += ", " + refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, strResult[j].ToString(), slang, "");
            }
            string strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout, "Game ID : " + GameId3rd, "Results", strImgUrl, strFinalScore);
        }

        private static string GetDragonTigerLayout(string sDesc, string slang, string GameId3rd, string bettype)
        {
            string[] GameDetail = sDesc.Split('*');
            string s1 = GetSplitValue('=', GameDetail[5].ToString());
            string[] CardValue = s1.Replace("D;", "").Replace("T;", "").Replace("0", "").Split(':');
            strBankerCardValue = CardValue[1].ToString();
            strPlayerCardValue = CardValue[0].ToString();
            RenderTemplate();

            string strRefKey = "SC_BT";
            string strFinalScore = refDataHelper.GetResourceDataByRefIdAndResourceId(strRefKey, GetSplitValue('=', GameDetail[7].ToString()), slang, "");
            string strScoreValue = GameDetail[6].ToString();
            string[] strScore = GetSplitValue('=', strScoreValue).Replace("D;", "").Replace("T;", "").Split(':');
            string strFinalLayout = GetFinalLayout(bettype);

            return String.Format(strFinalLayout, "Game ID : " + GameId3rd, "Dragon", "Tiger", strPlayerImg, strBankerImg, strScore[0].ToString(), strScore[1].ToString(), strFinalScore);
        }

        private static string GetSplitValue(char strSymbol, string strValue)
        {
            string[] strTemp = strValue.Split(strSymbol);
            return strTemp[1].ToString();
        }

        #region RenderTemplate 套用模板輸出網頁資料
        private static void RenderTemplate()
        {
            strPlayerImg = GetCardImgPath(strPlayerCardValue);
            strBankerImg = GetCardImgPath(strBankerCardValue);
        }
        #endregion

        private static string GetCardImgPath(string CardValue)
        {
            string SkinPath = (_ImgPath == "") ? @"template/public/game_result/" : _ImgPath;
            string strCardImg = "";
            string[] strCard = CardValue.Split(',');
            for (int j = 0; j < strCard.Length; j++)
            {
                if (strCard[j].Contains("<br/>"))
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString().Replace("<br/>", "") + ".png' align='absmiddle' border='0' class='code' />";
                    strCardImg += "<br/>";
                }
                else
                {
                    strCardImg += @"<img src='" + SkinPath + "Poker/" + strCard[j].ToString() + ".png' align='absmiddle' border='0' class='code' />";
                }

                //strCardImg += @"<img src='" + AppDomain.CurrentDomain.BaseDirectory + SkinPath + "Poker/" + strCard[j].ToString() + ".jpg' align='absmiddle' border='0' class='code' />";

            }
            return strCardImg;
        }

        private static string GenImgUrl(string sMode, string sResult)
        {
            string sImgUrl = "";
            string skinroot_path = (_ImgPath == "") ? @"template\public\game_result\" : _ImgPath;

            if (sMode == "Roulette")
            {
                skinroot_path += @"Roulette\";
                sImgUrl = "<img  src=\"" + skinroot_path + sResult + ".png\"  align=\"absmiddle\" border=\"0\" />";
            }
            else
            {
                skinroot_path += @"Sicbo\";
                string[] strResult = sResult.Split(';');
                string temp = "ScoreBoard_d";
                for (int j = 0; j < strResult.Length; j++)
                {
                    sImgUrl += "<img  src=\"" + skinroot_path + temp + strResult[j].ToString() + ".png\"  align=\"absmiddle\" border=\"0\" />";
                }
            }

            return sImgUrl;
        }

        private static string GetFinalLayout(string bettype)
        {
            string strFinalLayout = "";
            switch (bettype)
            {
                case "3101":
                case "3102":
                    strFinalLayout = "<div class='popWTableArea'><table width='100%' cellpadding='0' cellspacing='0' border='0' class='oddsTable info'>";
                    strFinalLayout += "<tbody><tr><td colspan='2' class='tabtitle'>{0}</td></tr></tbody>";
                    strFinalLayout += "<tbody>";
                    strFinalLayout += "<tr align='center'><th>{1}</th><th>{2}</th></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td width='50%'>{3}</td><td width='50%'>{4}</td></tr>";
                    strFinalLayout += "<tr align='center'> <td style='height: 24px;'>{5}</td> <td>{6}</td></tr>";
                    strFinalLayout += "<tr align='center'><td colspan='2' style='height: 24px; vertical-align:bottom;'>{7}</td></tr>";
                    strFinalLayout += "</tbody></table></div>";
                    break;
                case "3103":
                case "3104":
                    strFinalLayout = "<div class='popWTableArea'><table width='100%' cellpadding='0' cellspacing='0' border='0' class='oddsTable info'>";
                    strFinalLayout += "<tbody><tr><td class='tabtitle'>{0}</td></tr></tbody>";
                    strFinalLayout += "<tbody>";
                    strFinalLayout += "<tr align='center'><th>{1}</th></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td>{2}</td></tr>";
                    strFinalLayout += "<tr align='center' class='bgcpe'><td><b>{3}</b></td></tr>";
                    strFinalLayout += "</tbody></table></div>";
                    break;
            }
            return strFinalLayout;
        }

    }

